insert into public.capture_applications
  (tab_id, name, student_id, cohort, major, preferred_teammate, dates, participation, drinking, activities, other_activity, created_at)
select new_tab.id, a.name, a.student_id, a.cohort, a.major, a.preferred_teammate, a.dates, a.participation, a.drinking, a.activities, a.other_activity, a.created_at
from new_tab cross join applicants a;

update public.capture_rounds r
set dates = array['2026-11-16', '2026-11-17', '2026-11-18', '2026-11-19', '2026-11-20', '2026-11-21', '2026-11-22', '2026-11-23']::date[]
from public.tabs t
where t.id = r.tab_id and t.template = 'capture' and t.title = '캡처 예시' and t.deleted_at is null;

select count(*) as applications, count(distinct student_id) as people
from public.capture_applications a
join public.tabs t on t.id = a.tab_id
where t.title = '캡처 예시' and t.deleted_at is null;
